// Signs a write-back for LendLoop's Convex endpoints: HMAC-SHA256 over
// `${timestamp}.${body}` with N8N_TO_CONVEX_SECRET (container env, never in this JSON).
const crypto = require('crypto');
function signForConvex(payload) {
  const secret = $env.N8N_TO_CONVEX_SECRET;
  if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not set in the n8n container');
  const body = JSON.stringify(payload);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const digest = crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
  return { body, timestamp, signature: `v1=${digest}` };
}

return [{ json: signForConvex({ action: 'loans.listOverdue' }) }];

// One item per overdue loan. Convex already left out loans reminded today,
// so re-running this workflow on the same day sends nothing new.
const { asOf, loans } = $input.first().json;
console.log(`[lendloop] ${loans.length} overdue loan(s) as of ${asOf}`);
return loans.map((loan) => ({ json: { ...loan, asOf } }));

// Mock reminder, per borrower. A borrower we cannot reach is recorded as a
// failed reminder instead of stopping the run for everyone else.
const loan = $input.item.json;
if (!loan.borrower?.email) {
  return { json: { ...loan, status: 'failed', reason: 'no email address on file' } };
}
const masked = loan.borrower.email.replace(/^(.).*(@.*)$/, '$1***$2');
const days = loan.daysOverdue === 1 ? '1 day' : `${loan.daysOverdue} days`;
console.log(`[lendloop] MOCK REMINDER to=${masked} tool="${loan.toolName}" overdue=${days} idempotency-key=${loan.idempotencyKey}`);
return { json: { ...loan, status: 'sent', text: `Hi ${loan.borrower.firstName}, the ${loan.toolName} was due back on ${loan.endDate} (${days} ago). Please return it or message the owner.` } };

// Signs a write-back for LendLoop's Convex endpoints: HMAC-SHA256 over
// `${timestamp}.${body}` with N8N_TO_CONVEX_SECRET (container env, never in this JSON).
const crypto = require('crypto');
function signForConvex(payload) {
  const secret = $env.N8N_TO_CONVEX_SECRET;
  if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not set in the n8n container');
  const body = JSON.stringify(payload);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const digest = crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
  return { body, timestamp, signature: `v1=${digest}` };
}

const loan = $input.item.json;
const sent = loan.status === 'sent';
const days = loan.daysOverdue === 1 ? '1 day' : `${loan.daysOverdue} days`;
return { json: signForConvex({
  action: 'activity.record',
  // reminder:<loanId>:<date>. One success per loan per day; a failure gets its
  // own key so the loan is retried on the next run but never logged twice.
  idempotencyKey: sent ? loan.idempotencyKey : `${loan.idempotencyKey}:failed`,
  kind: sent ? 'reminder_sent' : 'reminder_failed',
  loanId: loan.loanId,
  summary: sent ? `Overdue reminder sent (${days} late)` : `Overdue reminder failed: ${loan.reason}`,
  workflow: $workflow.name,
  executionId: String($execution.id),
}) };
